<?php use App\Support\App;App::requireAdmin();$rows=App::db()->query('SELECT o.*,p.name product_name FROM orders o JOIN products p ON p.id=o.product_id ORDER BY o.id DESC LIMIT 200')->fetchAll();$title='Orders';require __DIR__.'/../layouts/head.php';?><main class="p-8 max-w-7xl mx-auto"><h1 class="text-2xl font-semibold">Orders</h1><div class="mt-4"><select id="status" class="field max-w-xs"><option value="processing">Processing</option><option value="success">Done</option><option value="rejected">Failed + Refund</option></select><button class="btn btn-dark" onclick="applyBulk()">Apply</button></div><div class="saas-card mt-5 p-4 overflow-auto"><table class="w-full"><?php foreach($rows as $r):?><tr class="border-b"><td><input class="oid" type="checkbox" value="<?=$r['id']?>"></td><td><?=$r['order_number']?></td><td><?=$r['imei']?></td><td><?=htmlspecialchars($r['product_name'])?></td><td><?=$r['status']?></td></tr><?php endforeach?></table></div></main><script>async function applyBulk(){let ids=[...document.querySelectorAll('.oid:checked')].map(x=>+x.value);let r=await fetch('/api/admin/orders/bulk',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify({ids,status:status.value})});Swal.fire(JSON.stringify(await r.json()));}</script><?php require __DIR__.'/../layouts/foot.php';?>